function onShow$Item(g) {
  var a = [];
  Array.add(a, {Name: 'stt_rec', Opr: '=', Value: '', Type: 'String', Ignore: false});
  g.set_externalKey(a);
  g.set_gridPageIndex(-2);
}
function load$GridReport$Item(g) {g.add_onRender(on$GridReport$Render$Item);}
function dispose$GridReport$Item(g) {try {g.remove_onRender(on$GridReport$Render$Item);} catch (ex) {}}
function on$GridReport$Render$Item(sender, eventArgs) {
  var g = eventArgs.grid;
  var mainSplitter = document._mainSplitter;
  g._divGrid.style.height = mainSplitter._left.cells("b").getHeight() - 120 + 'px';
}
